-- 006: Korean (ko) translations for places & dishes
INSERT INTO culinary_place_translations (culinary_place_id, language_id, name, short_description, description, history, cultural_significance, tourist_tips)
SELECT p.id, l.id, v.name, v.short_desc, v.descr, v.history, v.culture, v.tips
FROM (VALUES
  ('oc-oanh', '어안 조개집',
   '4군에서 유명한 길거리 해산물 조개 전문점으로, 오후부터 영업하며 남방식 진한 양념으로 일품.',  
   '어안 조개집은 4군 주민들이 즐겨 찾는 노천 해산물 포장마차로, 숯불 구이와 볶음 조개, 레몬그라스 찜 바지락 등이 대표 메뉴다. 인도에 놓인 작은 플라스틱 테이블에서 저녁에 친구들과 함께하기 좋다. 가게는 오후부터 밤늦게까지 운영돼 언제 가도 늘 웃음소리와 숯불 타는 소리가 끊이질 않는다. 특히 대부분 메뉴가 주문 즉시 조리돼 해산물 본연의 신선함과 수작업 감성의 진한 맛을 동시에 느끼게 하며, 살아있는 조개와 버터·마늘·고추·남부 향신료가 어우러진 독특한 풍미를 자랑한다. 시원한 얼음 녹차가 곁들여지고, 달달짭짤한 디핑 소스와 바삭하게 구운 라이스페이퍼가 이 맛을 더 균형감 있게 만들어준다. 현지인뿐 아니라 점점 더 많은 여행객들이 일부러 길거리 끝을 찾아와, 숯불 연기가 자욱한 포장마차의 분위기를 만끽하고 사진을 남기며 도시의 정수를 즐기고 있다. 일행은 보통 조개와 함께 구운 라이스페이퍼, 크리스피 프라이드 라이스, 시원한 맥주를 주문해 밤을 흥겹게 달군다. 간단한 안주거리로 구운 달걀, 버터 팝콘 같은 곁들임 음식도 준비되어 있어 식사 경험이 한층 풍성해진다. 주말이면 이곳은 젊은 친구들끼리 모이기 좋은 핫플레이스로 변모해 노천 식탁 위의 알록달록한 기억들은 누구든 한 번 다녀간 이에게 오래도록 남는 추억이 된다.',
   '가게는 도안반뀌(Đoàn Văn Cự) 거리에 자리해 오후 무렵부터 밤늦게까지 문을 연다. 메뉴의 중심은 매일 들어오는 신선한 조개류이고, 사이공식 조리법에 따라 숯불구이·마늘볶음·레몬그라스찜으로 낸다. 해산물은 매일 아침 항만과 강물에서 조리해 올라오므로 항상 살아있고 탱탱하다. 숯불 화덕은 종일 타올라 특유의 고소한 연기 향을 하루 내내 풍긴다. 가게에는 커다란 간판이 따로 없이 오직 음식과 오랜 고객들과의 정으로 버텨온 오랜 관계가 전부다. 요새는 SNS 속 활활 타오르는 숯불 사진이 젊은 손님들을 끌어들여, 미식 탐방 명소로 더욱 주목받고 있다. 세월이 흘러도 변하지 않은 것은 대대로 내려온 가족 양념과 손끝에서 나오는 맛으로, 이것이 이 집의 가장 밝은 유산이다.',
   '조개 요리는 퇴근 후 친구들과 모이는 사이공 길거리 음식 문화를 상징한다. 4군은 조개 전문점이 가장 많이 모여 있는 지역 중 하나로 꼽힌다. 숯불의 색감과 열기, 진한 맛이 어우러지며 이 거리 미식의 하이라이트를 이루고, 옛날 해양·항만 교역 역사와도 닿아 있다. 현지 사람들에게 조개집은 하루 일을 마친 뒤 친구들을 만나 수다를 떨고 정을 나누는 비격식 공간이며, 화려하진 않아도 속 깊은 맛이 있는 진정한 쉼터다.',
   '오후 6시 이후 방문해 야시장 분위기를 즐겨보세요 • 구운 라이스페이퍼나 바삭한 반짱과 함께 먹으면 좋습니다 • 많은 가게가 현금만 받으니 현금을 챙기세요 • 소금고추 쫀득 달팽이를 레몬잎과 함께 드셔보세요 • 직원 추천 조합으로 맛있게 즐기기'),
  ('com-tam-vinh-khanh', '빈카인 콤딤',
   '빈카인 거리에 있는 사이공식 콤딤(찹쌀밥) 전문점, 숯불 돼지갈비와 계란찜 곁들임, 남쪽 미각의 대표선.',    
   '이 콤딤 가게는 숯불에 구운 돼지갈비, 견과류 튀김(삐)과 계란찜을 새콤달콤 피시소스에 곁들여 낸다. 이 지역 노동자들의 일상적인 점심과 저녁 식사다. 콤딤 전문점으로 잘 알려져 있으며, 정통 베트남식 맛의 결을 그대로 살리는 곳이다. 가장 유명한 것은 숯불 돼지갈비로, 양념에 재운 갈비가 붉은 숯 위에서 바로 구워져 윤기 흐르는 색, 특유한 훈연 향, 저항할 수 없는 맛을 선사한다. 더불어 바삭하게 튀긴 돼지껍데기(삐), 부드러운 계란찜 등 여러 곁들임 메뉴가 있어 각자 취향에 맞게 고를 수 있다. 자체적으로 배합한 새콤달콤한 피시소스는 짠맛·단맛·산미의 조화를 이뤄 돼지갈비와 어우러지며 풍미를 한층 끌어올린다. 밥에는 돼지고기 소시지, 토마토, 쪽파가 한 번 더 올라가 복합적인 맛을 완성한다. 이곳은 단순 밥집을 넘어 직장인들과 학생들이 수업·외출 후 들르는 약속 장소다. 플라스틱 의자, 햇빛이 가득한 거리 식당 분위기, 바닥에 남아 있는 숯 냄새 등이 독특한 정취를 만든다. 허물어가는 청백색 벽, 지친 손님들이 항상 찾는 이 밥집에는 가게 주인의 30년 가까운 노력이 어려 있다. 콤딤은 옛날 가난한 이들의 양식이었으나, 이제는 누구나 사이공에서 꼭 먹어야 하는 길거리 미식으로 올라섰다.',
   '돼지갈비는 숯불 겨에 노릇하게 구워지고, 찹쌀밥은 알이 또렷하며 바삭하게 튀긴 삐와 계란찜이 곁들여진다. 생선소스에는 토마토와 볶은 양파가 들어간다. 빈카인 거리는 오랫동안 4군에서 가장 번화한 음식 거리로, 값싼 콤딤 가게들이 밀집해 있다. 가게는 처음엔 선풍기 한 대, 피시소스 한 항아리, 양념한 돼지고기 한편에서 시작했다. 콤딤은 과거 서민의 양식이었지만 이제는 사이공에 오는 누구도 놓칠 수 없는 거리 음식의 정점이 되었다. 가게 바깥 벽면의 푸른색이 바랬고, 유리창 너머로 정오의 햇살이 요동친다. 숯불 담당자는 밤늦도록 화로를 지키며 앉아서 고기를 뒤집는다. 단골이 매주 찾아오는데 젖먹이 적부터 온 사람, 지금은 타지에서 일하는 사람까지 모두 그 맛을 못 잊어 찾아온다.',
   '콤딤은 찹쌀을 활용한 남부의 국민 음식으로 여겨지며, 오늘날 사이공 거리 음식의 상징이 되었다. 콤딤은 사람에게서 버림받은 것을 다시 빛내 보인 창조의 맛과 궁핍을 이겨낸 지혜를 보여준다. 요리사의 정성, 불 앞에서 땀 흘린 손, 맛 예술이 벽 너머로 이어지는 서민적 결을 담고 있다. 이 맛이 한 그릇 콤딤을 저마다의 사연 품은 거리 미식의 징표로 남게 만든다.',
   '11시~13시는 혼잡하니 조금 기다릴 수 있습니다 • 계란후라이나 차빼(소시지)를 추가해보세요 • 피시소스를 살짝 찍어 깨알 같은 맛을 잡아보세요 • 길거리 음식에 묻혀도 건강을 챙기세요'),
  ('banh-xeo-hoa-gia', '화자 반쎄오',
   '숯불에 방금 구워낸 바삭한 베트남 반쎄오, 쌈 채소와 소스에 말아 먹는 남부 미각의 정석.',    
   '반쎄오는 얇고 바삭한 크레이프에 새우, 돼지고기, 콩나물을 넣고 주문 즉시 구워 바삭함을 유지한다. 상추와 허브, 라이스페이퍼에 말아 새콤달콤 피시소스에 찍어 먹는 음식이다. 주재료는 쌀가루·강황·새우·돼지고기·콩나물·신선 채소로, 전통 비법과 손기술이 어우러져 매 장마다 황금빛 바삭한 껍질이 생긴다. 갓 나온 반쎄오는 씹을 때 사각거림, 고기·새우의 풍미, 강황이 퍼하는 고소함이 복합적으로 퍼져간다. 사이공식 곁들임 방식은 상추·허브·절임 채소를 한데 말아 당근·무절임이 들어간 새콤 피시소스에 찍어 먹는 것이다. 단순한 한 끼를 넘어 반쎄오는 즐거운 길거리 분위기를 자아내며, 유머와 가족적 정서와 나눔의 마음을 낳는 연결고리다. 반쎄오야말로 남부 일상의 진수를 보여주는 음식, 소박하고 친근하고 따뜻한 삶의 한 장면 같은 것이기도 하다.',
   '사이공 사람들은 반쎄오를 상추, 민트, 짠 채소와 함께 말아 당근과 무 절임이 들어간 피시소스에 찍어 먹는 것이 일반적이다. 응우옌꽈이(Nguyễn Khoái) 거리의 반쎄오 포장마차들은 오랫동안 가족 단위 노점 형태로 동네 주민들에게 음식을 제공해 왔다. 반쎄오는 논농사철·맑은 물·입맛을 잃지 않는 계절과 연결되어 있어, 계절의 변화와 토지에서 자라는 재료의 친밀함을 함께 맛보게 한다. 예전부터 강가 가까운 이 거리의 반쎄오 노점들은 동네 소상공인의 형태로 지속돼 왔다.',
   '반쎄오는 강황 특유의 노란빛과 신선한 허브가 특징인 남부 음식 문화의 융합을 보여준다. 반쎄오는 남부 미식의 섞임, 강황의 금빛과 집에서 딴 허브, 전통과 변화를 담으며 일상 속 미감이 어떤 모양인지 보여준다. 아울러 이 음식은 척박한 시절 한 줌 쌀에서 시작된 궁리가 지금 한 끼 풍성한 기억으로 이어졌음을 전한다.',
   '갓 나온 상태에서 먹어야 가장 바삭합니다 • 소스에 찍기 좋게 작게 말아 보세요 • 많은 가게가 현금을 선호하니 현금을 준비하세요 • 야외 숯불 느낌을 느끼고 싶다면 편안한 옷차림으로 방문해보세요'),
  ('bun-rieu-ben-van-don', '벤반돈 분리에우',
   '달콤하고 맑은 게육국에 말은 분리에우, 쌈 채소와 새우장과 함께 먹는 강변 아침의 맑은 국물.',    
   '게 알이 덩어리진 국물은 맑고 달콤하며, 생면(후엔), 두부, 토마토와 각종 쌈 채소가 함께 나온다. 강변 지역에서 흔한 아침과 점심 식사다. 민물게를 갈아 체에 걸러 게 알을 내고, 토마토와 함께 끓여 자연스러운 붉은색을 낸다. 면에는 새우장·물고추냉이·콩나물과 바나나꽃 채가 곁들여진다. 벤반돈 일대는 강 부두와 가까워 오랫동안 동네 주민들을 위한 아침 식사 가게들이 모여 있었다. 분리에우는 남부의 대표적인 아침 식사로, 물의 도시 음식 특유의 담백한 간을 보여준다.',
   '게 알은 민물게를 으깨어 체로 걸러내고 토마토와 함께 끓여 자연스러운 붉은빛을 얻는다. 떼(면)에는 새우장·물고추냉이·콩나물·바나나꽃채 등이 어우러지고, 강가 부두 근처 거리에는 오랫동안 동네 주민들을 위한 아침 식당들이 모여 있었다. 민물게의 은은한 달큰함이 국물에 스며들어, 강이 가까운 곳 특유의 맑은 아침을 떠올리게 한다.',
   '분리에우는 남부의 대표적인 아침 식사로, 물의 도시 음식 특유의 담백한 간을 보여준다. 분리에우는 강 하구가 만들어내는 아침의 고요와 도로 일상의 리듬, 강물에 기대 살았던 사람들의 밥상을 그대로 반영한다. 시장에 안개 낀 아침, 이미 불은 꺼져 있으나 솥은 여전히 남아 있는 풍경 속에서 이 음식의 역사가 전해진다.',
   '진한 맛을 원하면 게 알을 추가하세요 • 카람(청귤)을 짜 넣으면 풍미가 살아납니다 • 현금을 챙기세요, 카드를 거부하는 가게가 있습니다 • 새벽녘 강가의 고요한 시적 분위기를 함께 즐겨보세요'),
  ('pho-an-vinh-khanh', '빈카인 야식 거리',
   '4군에서 가장 활기찬 야식 거리: 해산물 구이, 조개 요리와 전골이 가득, 밤이면 차려지는 미식의 온통 무대.',    
   '해 질 녘 빈카인 거리는 야식의 거리로 변모한다. 길가에 플라스틱 테이블이 줄지어 늘어서고 해산물 구이와 전골의 향이 가득하다. 사이공의 밤 문화를 느끼기에 가장 좋은 곳이다. 길가 노점에서는 해산물 구이,각종 조개 요리, 생선 전골과 해산물 죽을 판다. 밤 7시부터 11시가 가장 붐비는 시간이다. 이 거리는 항구 지역 주민들의 야식 수요에서 시작해 점차 도시 전체의 단골들이 찾는 심야 미식 거리로 발전했다. 빈카인 야식 문화는 플라스틱 의자에 앉아 싱싱한 요리를 즐기며 밤늦게까지 대화를 나누는 사이공의 개방적 삶을 보여준다.',
   '빈카인 거진 해 질 무렵이면 전체가 야식 거리로 바뀌어 플라스틱 테이블이 줄줄 이어지고 해산물 그릴과 전골 냄새가 진동한다. 길가 노점은 구운 해산물,각종 조개, 생선 전골, 해산물죽을 제공한다. 밤 19시~23시 가장 인파가 많고, 냄새가 거리 전체에 번진다. 원래 이 거리는 항구 주변 주민들의 야식 필요로부터 시작해 점점 전 도시 사람들이 한식처럼 들르는 자정 미식 거점으로 커졌다. 플라스틱 의자에 앉아 싱싱한 음식을 나누고 밤 깊이까지 떠드는 이 풍경은 사이공의 서늘한 밤문화 그대로를 비춘다.',
   '빈카인 거리는 첫 출발점부터 항만 주변 거주자들의 밤참 요구로부터 시작해 점차 도시 전체의 미식 목적지로 바뀌었다. 이곳은 길거리 음식의 전성기, 야시장 분위기와 불빛, 소리,냄새 일체의 살아있는 거리 미학이다. 빈카인 거리의 사람들은 벌써 4·50년 가량이 넘는 이 거리에서 야식의 정겨운 에너지를 마음껏 나눠 왔다.',
   '여럿이 함께 가서 여러 요리를 나눠 먹는 것을 추천합니다 • 현금만 받는 가게가 많으니 현금을 챙기세요 • 긴 하루 뒤에도 식탁 위의 웃음이 끊이지 않는 빈카인 거리에서 천천히 밤맛에 젖어보세요'),
  ('cho-quan-4', '4군 시장',
   '아침 음식, 과일과 남부 특산품이 모이는 전통 시장, 로컬 식재의 본바닥 직거래 현장.',    
   '4군 시장에는 아침 음식 노점, 신선한 과일, 떡과 해산물 건어물 가게들이 모여 있다. 전통 사이공식 시장 분위기 속에서 현지 음식 문화를 탐험하기에 좋다. 시장 안 노점에선 분맘(발효 생선 국수), 쭈티에우, 반칸, 남부 과일과 건어물을 판다. 아침이 시장이 가장 바쁜 시간이다. 수십 년간 이 시장은 4군 주민들의 식재료 구매 중심지였고 이웃 동네에도 신선한 재료를 공급해왔다. 전통 시장은 현대 쇼핑몰과 달리 현지인의 사고·요리·먹는 원형을 보존하는 공간이다.',
   '4군 시장의 노점에는 분맘·훠티에우·반칸과 남부 지방에서 나는 과일, 건어물 등이 진열된다. 가장 분주한 시간은 아침이다. 수십 년간 이 시장은 4군 주민들의 식재료를 책임지는 중심이었고 인근 거주지에 신선한 재료를 대주는 역할을 해왔다. 전통 시장은 현대 쇼핑센터와 대비되는, 토박이 상인·요리·가정식 식사의 원형적 모습을 그대로 안고 있는 곳이다.',
   '4군의 전통 시장은 동네 식료 보급의 굳은 중심이었던 동시에 향토 상인·요리·식사의 원래 풍경을 간직한 살아있는 공간이다. 시장은 세월이 가도 본래의 사람 냄새, 비닐 천막, 긁어모은 웃음, 아침 햇살에 반사된 과일 빛 등 예전 그대로를 간직하며, 도시인의 마음을 편안하고 자연스럽게 섞이게 한다.',
   '잔돈을 준비하면 구매가 편리합니다 • 노점 주인에게 그 자리에서 먹을 아침 메뉴를 추천받아 보세요'),
  ('cafe-ben-van-don', '벤반돈 강변 카페',
   '운하가 내려다보이는 강변 카페로, 아침과 저녁 산책에 적합하며 느릿한 사이공 수변의 한 때.',    
   '강을 향해 열린 공간에서 연유 커피, 코코넛 커피와 과일차를 판다. 음식점이 밀집한 4군에서 잠시 쉬어가기 좋은 곳이다. 카페는 벤반돈 거리를 따라 운하를 바라보며 있고, 앞쪽 좌석에서 오가는 배를 구경할 수 있다. 벤반돈은 예전에 이 지역의 번성했던 강 항구로, 현재는 4군과 1군을 연결하는 번화한 거리다. 사이공 길거리 커피 문화는 분주한 도심 속의 느긋한 삶의 리듬을 보여준다.',
   '카페는 벤반돈 거리 따라 자리해 마주 보이는 운하와 배로 붐비는 앞마당을 가졌다. 벤반돈은 오래전 이 지역에서 번성하던 강 항구였으며 지금은 4군과 1군을 잇는 분주한 도로다. 그 시절의 배에 실린 물건들과 오가는 사람들의 삶이 강물에 희미하게 남아 있다.',
   '사이공 길거리 커피 문화는 바쁘게 돌아가는 도시 한복판에서 느긋하게 살아가는 리듬을 드러낸다. 이 강변 카페는 점점이 이어진 거리 식당 속에서도 잠깐 멈춰 숨 돌리고 물가 옆 풍경과 배들의 지나감을 바라보며 일상의 속도를 늦추는 장소로 의미가 깊다.',
   '아침 이른 시간이 시원하고 배들이 오가는 모습을 볼 수 있습니다 • 전통 핀(드립) 방식의 연유 커피를 주문해보세요'),
  ('che-heo-quay', '체(전통 디저트) 가게',
   '길거리 전통 디저트 가게로, 체 닥찜(모듬 디저트)과 시원한 흰 케이크 체가 대표, 오후 골목의 단맛.',    
   '체 닥찜 한 그릇에는 녹두, 타로, 사고와 코코넛밀크가 어우러지며 그 밖에 백옥체와 태국식 체도 있다. 저녁에 동네 주민들이 즐기는 디저트 명소다. 체는 매일 새로 끓이며 오후부터 밤까지 판다.각종 체는 코코넛밀크 고소한 남부식 단맛을 지닌다. 이런 디저트 노점은 골목 안쪽에 자리 잡고 오랫동안 지역 주민들의 사랑을 받아 왔다. 체(전통 디저트)는 남부의 디저트 문화로, 녹두·타로·코코넛 같은 물길 재료의 풍요로움을 반영한다.',
   '체 닥찜에는 녹두·타로·사고코코넛밀크가 섞이고, 백옥체와 태국식 체도 함께 낸다. 체는 매일 새로 끓여 오후부터 밤늦도록 판매하며, 코코넛밀크의 깊은 단맛은 남부 특유의 풍미를 잘 보여 준다. 골목 깊숙이 자리한 이런 디저트 노점은 오랜 세월 동네 사람들에게 사랑받으며 전승돼 왔다.',
   '체(전통 디저트)는 남부의 디저트 문화로, 녹두·타로·코코넛 등 강 하구 지역의 풍부한 농산물을 반영한다. 체는 한 그릇에 계절 재료와 사람들의 소박한 입맛이 겹쳐져, 달콤함이 오래 남는 골목의 정서를 만든다.',
   '저녁에 드실 때는 얼음을 적게 넣어 달라고 하세요 • 구운 땅콩을 뿌리면 고소함이 더해집니다'),
  ('banh-canh-cua-nguyen-khoai', '응우옌꽈이 게 반칸',
   '게육 진한 국물에 말은 반칸(굵은 쌀국수), 응우옌꽈이 일대의 아침 명물, 강가 아침밥의 진한 국물.',    
   '쌀가루와 타피오카가루로 만든 쫄깃한 면발에 게와 돼지뼈로 우린 국물, 게살 완자와 새우, 시나몬 소시지가 곁들여진다. 4군의 진한 아침 식사다. 알찐 게살이 달콤하고 쫄깃하며 게와 돼지뼈를 함께 우려 국물이 자연스럽게 걸쭉해진다. 콩나물, 파, 갈은 후추와 약간의 고추를 곁들인다. 응우옌꽈이 거리의 게 반칸 노점들은 오랫동안 가족 단위 아침 포장마차 형태로 동네 주민들에게 음식을 제공해 왔다. 게 반칸은 많은 사람에게 강변 지역 아침 음식 문화의 대표로 여겨진다.',
   '살 꽉 찬 게는 달콤쫄깃하고, 게와 돼지뼈를 같이 우러나 국물이 자연스럽게 걸쭉해진다. 면에는 콩나물·쪽파·갓 간 후추·약간의 고추가 올라가고, 응우옌꽈이 거리 게 반칸 노점들은 오랫동안 가족 운영 아침 포장마차로 동네 사람들에게 끼니를 제공해왔다. 강가 지역은 이 진한 아침 국물로 수많은 하루를 깨웠다.',
   '게 반칸은 많은 이들에게 강가 지역 아침 미식 문화의 상징처럼 여겨지는 음식이다. 게 반칸은 민물 게에서 나오는 단단한 단맛과 정성으로 우리는 국물이, 강 근처 아침의 무게와 사람들의 생활 결을 드러낸다. 강가 아침이면 이미 피어오르는 국물의 김만 봐도 하루를 시작하는 기분이 난다.',
   '원하면 시나몬 완자를 추가하세요 • 짠 토마토 절임을 곁들이면 느끼함이 줄어듭니다'),
  ('hutieu-ca-men', '미투 꾸티에우',
   '맑고 달콤한 국물의 미투식 꾸티에우, 싱싱한 새우와 부추, 튀긴 마늘을 곁들인 강남부 국수.',    
   '미투 꾸티에우 한 그릇: 살짝 분홍빛이 도는 쫄깃한 면에 싱싱한 새우, 돼지고기, 간과 청경채, 맑고 달큰한 국물이 어우러진다. 꾸티에우 면은 쌀가루에 새우를 섞어 연분홍색을 냈으며, 육수는 돼지뼈와 피시소스로 은은하게 우린다. 이 가게는 미투 스타일로 여러 해 동안 도안류하이(Đoàn Như Hài) 지역 주민들에게 음식을 제공해 왔다. 꾸티에우는 남부에서 베트남·중국·크메르 음식 문화가 융합된 모습을 보여주며, 물국물과 건더기 두 가지 스타일이 모두 흔하다.',
   '꾸티에우 면은 쌀가루에 새우를 섞어 연분홍색이 돌고, 육수는 돼지뼈와 피시소스로 은은하게 우린다. 이 가게는 미투 스타일로 수년 동안 도안류하이 지역 주민들의 밥을 차려주며 이어 왔다. 꾸티에우는 베트남·중국·크메르 요리의 섞임을 보여주고 국물과 마른 국수 두 가지 스타일로 모두 즐길 수 있다.',
   '꾸티에우는 남부에서 베트남·중국·크메르 요리가 섞인 모습을 드러내며, 국물이 있는 스타일과 마른 스타일 모두 흔하다. 꾸티에우의 국물 향, 미투 특유의 면 색, 새우·간장·공심채의 조화는 강사람이 오래 지켜온 맛의 예로 남부의 다문화 이력과 닿아 있다.',
   '물국물과 건더기 두 가지 스타일 모두 경험해 보세요 • 고추 식초를 약간 넣으면 국물 맛이 더 깊어집니다')
) AS v(code, name, short_desc, descr, history, culture, tips)
JOIN culinary_places p ON p.code = v.code
JOIN languages l ON l.code = 'ko'
ON CONFLICT (culinary_place_id, language_id) DO NOTHING;

INSERT INTO dish_translations (dish_id, language_id, name, description, ingredients)
SELECT d.id, l.id, v.name, v.descr, v.ingr
FROM (VALUES
  ('oc-huong', '맛조개 구이', '숯불 구이 또는 버터 마늘 볶음, 도톰하고 달콤한 살이 특징으로 이 가게에서 가장 많이 주문되는 메뉴입니다.', '싱싱한 맛조개, 버터, 마늘, 고싱, 파'),
  ('nghieu-hap-sa', '레몬그라스 바지락 찜', '싱싱한 바지락을 레몬그라스와 고추와 함께 쪄서 국물이 시원하게 달콤하고, 레몬 소스에 찍어 먹습니다.', '바지락, 레몬그라스, 고추, 베트남 허브'),
  ('com-tam-suon-bi-cha', '숯불 돼지갈비 콤딤', '숯불에 구워 향이 진한 돼지갈비에 바삭한 삐(튀긴 돼지껍데기), 계란찜, 새콤달콤 피시소스를 찰밥 위에 얹습니다.', '찹쌀, 돼지갈비, 삐(돼지 껍질 튀김), 계란찜, 피시소스'),
  ('banh-xeo-tom-thit', '새우 반쎄오', '노릇하고 바삭한 베트남 반쎄오에 새우, 돼지, 콩나물을 넣고 쌈 채소에 말아 피시소스에 찍어 먹습니다.', '쌀가루, 강황, 새우, 돼지고기, 콩나물, 쌈 채소'),
  ('bun-rieu-cua', '게 분리에우', '게 알이 덩어리져 토마토 국물에 말은 국수와 두부, 생면, 각종 쌈 채소, 새우장을 곁들입니다.', '민물게, 토마토, 두부, 생면, 새우장'),
  ('lau-hai-san-vinh-khanh', '해산물 전골', '여러 사람이 나눠 먹는 해물 전골입니다. 새우·오징어·바지락이 살짝 매콤한 국물과 어우러지고 채소와 면을 곁들입니다.', '새우, 오징어, 바지락, 전골 국물, 채소'),
  ('oc-buong-nuong', '소금 고추 달팽이 구이', '소금과 고추로 숯불에 구운 달팽이로 쫄깃한 살이 빈카인 야식 거리의 대표 안주 인기입니다.', '달팽이, 소금, 고추, 라임잎'),
  ('bun-mam-cho', '분맘(발효 생선 국수)', '발효 생선의 진하고 개성 있는 육수에 새우, 오징어, 바다생선과 허들로 마무리합니다.', '발효 생선, 새우, 오징어, 바다 생선, 면, 허브'),
  ('ca-phe-sua-da-phin', '핀 연유 아이스 커피', '전통 핀 드리핑으로 내린 진한 커피와 연유·얼음이 어우집니다.', '로부스타 커피 원두, 연유, 얼음'),
  ('che-thap-cam', '체 닥찜(모듬 디저트)', '녹두·타로·사고·코코넛밀크가 한 그릇에 어우러진 전통 디저트입니다.', '녹두, 타로, 사고, 코코넛밀크, 설탕'),
  ('banh-canh-cua-bap', '게 반칸', '쫄깃한 면발에 게와 돼지뼈로 낸 걸쭉한 국물, 게살 완자와 새우를 곁들입니다.', '알찬 게, 쌀가루, 타피오카 전분, 새우, 시나몬 완자'),
  ('hu-tieu-my-tho', '미투 꾸티에우', '연하게 분홍빛 도는 쫄깃한 면에 싱싱한 새우·돼지고기·간, 맑고 달콤한 국물이 어우러집니다.', '쌀가루, 새우, 돼지고기, 간, 공심채')
) AS v(code, name, descr, ingr)
JOIN dishes d ON d.code = v.code
JOIN languages l ON l.code = 'ko'
ON CONFLICT (dish_id, language_id) DO NOTHING;
